package app.daemon.deck;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.media.*;import org.json.*;
public class Alarms {
 static final String CHANNEL="mission_notifications_v3",RINGING="mission_ringing_v3";
 static Intent eventIntent(Context c,JSONObject a)throws Exception{return new Intent(c,AlarmReceiver.class).setData(Uri.parse("daemon://alarm/"+Uri.encode(a.getString("id")))).putExtra("eventId",a.getString("id")).putExtra("at",a.getLong("at")).putExtra("title",a.getString("title")).putExtra("body",a.getString("body")).putExtra("type",a.optString("type","notification")).putExtra("sound",a.optString("sound","")).putExtra("volumeDismiss",a.optBoolean("volumeDismiss",true));}
 static PendingIntent pending(Context c,JSONObject a)throws Exception{return PendingIntent.getBroadcast(c,0,eventIntent(c,a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static JSONArray read(Context c)throws Exception{return new JSONArray(c.getSharedPreferences("alarms",0).getString("plan","[]"));}
 static void save(Context c,JSONArray plan){c.getSharedPreferences("alarms",0).edit().putString("plan",plan.toString()).commit();}
 static JSONArray unique(JSONArray plan)throws Exception{java.util.Map<String,JSONObject> map=new java.util.LinkedHashMap<>();for(int j=0;j<plan.length();j++){JSONObject a=plan.getJSONObject(j);map.put(a.getString("id"),a);}JSONArray out=new JSONArray();for(JSONObject a:map.values())out.put(a);return out;}
 static void scheduleNext(Context c,JSONArray plan)throws Exception{JSONObject next=null;for(int j=0;j<plan.length();j++){JSONObject a=plan.getJSONObject(j);if(next==null||a.getLong("at")<next.getLong("at"))next=a;}if(next!=null)((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,Math.max(System.currentTimeMillis()+100,next.getLong("at")),pending(c,next));}
 static long nextCycle(JSONObject cycle)throws Exception{JSONObject r=cycle.getJSONObject("rule");JSONArray days=r.getJSONArray("weekdays");int[] weekdays=new int[days.length()];for(int i=0;i<days.length();i++)weekdays[i]=days.getInt(i);return Recurrence.next(java.time.Instant.parse(cycle.getString("currentOriginalAt")).toEpochMilli(),java.time.Instant.parse(cycle.getString("currentOriginalAt")).toEpochMilli(),r.getString("frequency"),r.getInt("interval"),weekdays,r.getString("monthlyMode"),r.getInt("monthDay"),r.getInt("weekOrdinal"),r.getInt("weekday"),"last".equals(r.getString("missingDay")),"until".equals(r.getString("end"))?r.getString("until"):"","count".equals(r.getString("end"))?r.getInt("count"):10000,cycle.getInt("occurrence"),java.time.ZoneId.systemDefault().getId());}
 static JSONObject event(String id,long at,String title,String body,String type,String sound,boolean dismiss)throws Exception{return new JSONObject().put("id",id).put("at",at).put("title",title).put("body",body).put("type",type).put("sound",sound).put("volumeDismiss",dismiss);}
 static long deadlineFor(JSONObject cycle,long original)throws Exception{JSONObject overrides=cycle.optJSONObject("overrides");if(overrides==null)return original;java.time.ZoneId zone=java.time.ZoneId.systemDefault();String day=java.time.Instant.ofEpochMilli(original).atZone(zone).toLocalDate().toString();java.util.Iterator<String> keys=overrides.keys();while(keys.hasNext()){JSONObject o=overrides.getJSONObject(keys.next());String sourceDay=java.time.Instant.parse(o.getString("originalAt")).atZone(zone).toLocalDate().toString();if(day.equals(sourceDay))return java.time.Instant.parse(o.getString("deadline")).toEpochMilli();}return original;}
 static void appendCycle(JSONArray plan,JSONObject source,long now)throws Exception{if(!source.has("cycle"))return;JSONObject cycle=new JSONObject(source.getJSONObject("cycle").toString());long previous=java.time.Instant.parse(cycle.getString("currentOriginalAt")).toEpochMilli(),next=nextCycle(cycle);for(int skip=0;next>0&&deadlineFor(cycle,next)<=now&&skip<10000;skip++){previous=next;cycle.put("currentOriginalAt",java.time.Instant.ofEpochMilli(next).toString()).put("occurrence",cycle.getInt("occurrence")+1);next=nextCycle(cycle);}if(next<=0||deadlineFor(cycle,next)<=now)return;long due=deadlineFor(cycle,next);
  long available=Math.max(previous,next-86400000L);cycle.put("currentOriginalAt",java.time.Instant.ofEpochMilli(next).toString()).put("occurrence",cycle.getInt("occurrence")+1);String prefix=cycle.getString("seriesId")+":cycle:"+cycle.getInt("occurrence"),title=source.getString("title"),notice=cycle.optString("notificationSound",""),alarm=cycle.optString("alarmSound","");boolean dismiss=cycle.optBoolean("volumeDismiss",true);int count=cycle.optInt("reminderCount",0);JSONArray flags=cycle.optJSONArray("alarms");String date=java.time.Instant.ofEpochMilli(due).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"));
  for(int i=0;i<count;i++){long at=previous+(due-previous)*(i+1)/(count+1);boolean ringing=flags!=null&&flags.optBoolean(i,false);if(at>now&&at>=available)plan.put(event(prefix+":pre:"+i,at,title,"Pre-reminder "+(i+1)+"/"+count+" · Due "+date,ringing?"alarm":"notification",ringing?alarm:notice,dismiss));}
  boolean dueAlarm=cycle.optBoolean("dueAlarm",false);plan.put(event(prefix+":due",due,title,"Mission due now.",dueAlarm?"alarm":"notification",dueAlarm?alarm:notice,dismiss).put("cycle",cycle));
  if(cycle.optBoolean("overdueEnabled",true)){long period=Math.max(1,Math.min(365,cycle.optInt("overdueDays",2)))*86400000L,end=nextCycle(cycle),cutoff=end>0?Math.max(next,end-86400000L):0,at=due+period;if(cutoff==0||at<cutoff)plan.put(event(prefix+":overdue",at,title,"Mission overdue · Due "+date,"notification",notice,dismiss).put("repeatEvery",period).put("repeatUntil",cutoff));}
 }
 static void appendRepeat(JSONArray plan,JSONObject a,long now)throws Exception{long interval=a.optLong("repeatEvery",0);if(interval<=0)return;long at=a.getLong("at");at+=Math.max(1,(now-at)/interval+1)*interval;long until=a.optLong("repeatUntil",0);if(until==0||at<until){a.put("at",at);plan.put(a);}}
 public static synchronized String set(Context c,String json){try{JSONArray next=new JSONArray(json);if(next.length()>100000)throw new Exception("Too many reminders");AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray old=read(c);for(int i=0;i<old.length();i++)am.cancel(pending(c,old.getJSONObject(i)));JSONArray normalized=new JSONArray();long now=System.currentTimeMillis();for(int i=0;i<next.length();i++){JSONObject a=next.getJSONObject(i);if(a.getLong("at")>now)normalized.put(a);else{appendRepeat(normalized,a,now);appendCycle(normalized,a,now);}}normalized=unique(normalized);save(c,normalized);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())return "Exact scheduling access required.";scheduleNext(c,normalized);return "";}catch(Exception e){return "Reminder scheduling failed: "+e.getMessage();}}
 // Take the entire due batch in one wake-up; stale cancelled broadcasts cannot resurrect reminders.
 static synchronized JSONArray takeDue(Context c,Intent intent){JSONArray due=new JSONArray();try{JSONArray plan=read(c);boolean valid=false;for(int i=0;i<plan.length();i++){JSONObject a=plan.getJSONObject(i);if(a.getString("id").equals(intent.getStringExtra("eventId"))&&a.getLong("at")==intent.getLongExtra("at",-1))valid=true;}if(!valid)return due;JSONArray next=new JSONArray();long now=System.currentTimeMillis();for(int i=0;i<plan.length();i++){JSONObject a=plan.getJSONObject(i);if(a.getLong("at")<=now){due.put(a);appendRepeat(next,new JSONObject(a.toString()),now);appendCycle(next,a,now);}else next.put(a);}next=unique(next);save(c,next);scheduleNext(c,next);}catch(Exception ignored){}return due;}
 public static void restore(Context c){try{set(c,read(c).toString());}catch(Exception ignored){}}
 public static void channel(Context c){notificationChannel(c,"");NotificationChannel ring=new NotificationChannel(RINGING,"Ringing alarms",NotificationManager.IMPORTANCE_HIGH);ring.setSound(null,null);ring.enableVibration(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ring);}
 static String notificationChannel(Context c,String sound){if(!sound.isEmpty())try{android.content.res.AssetFileDescriptor f=c.getContentResolver().openAssetFileDescriptor(Uri.parse(sound),"r");if(f==null)sound="";else f.close();}catch(Exception e){sound="";}String id=sound.isEmpty()?CHANNEL:CHANNEL+"_"+Integer.toHexString(sound.hashCode());NotificationChannel ch=new NotificationChannel(id,"Mission notifications",NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);Uri uri=sound.isEmpty()?RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION):Uri.parse(sound);ch.setSound(uri,new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION).build());((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);return id;}
 static Notification notification(Context c,Intent i,boolean alarm){channel(c);Intent open=new Intent(c,alarm?AlarmActivity.class:MainActivity.class).putExtras(i).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent content=PendingIntent.getActivity(c,alarm?1:0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder n=new Notification.Builder(c,alarm?RINGING:notificationChannel(c,i.getStringExtra("sound")==null?"":i.getStringExtra("sound"))).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(i.getStringExtra("title")).setContentText(i.getStringExtra("body")).setStyle(new Notification.BigTextStyle().bigText(i.getStringExtra("body"))).setCategory(alarm?Notification.CATEGORY_ALARM:Notification.CATEGORY_REMINDER).setContentIntent(content).setAutoCancel(!alarm);if(alarm){PendingIntent stop=PendingIntent.getBroadcast(c,2,new Intent(c,AlarmReceiver.class).setAction("dismiss"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.setOngoing(true).setFullScreenIntent(content,true).addAction(new Notification.Action.Builder(null,"Dismiss",stop).build());}return n.build();}
}
